from itertools import chain, repeat


def ncycles(iterable, n):
    """Returns the sequence elements *n* times

    >>> list(ncycles(["a", "b"], 3))
    ['a', 'b', 'a', 'b', 'a', 'b']

    """
    if n < 0:
        raise ValueError("n must be non-negative")
    items = tuple(iterable)
    return chain.from_iterable(repeat(items, n))
